flowchart TB
  CLI(["クライアント"])
  subgraph VPC["VPC"]
    ALB@{ svc: "Elastic Load Balancing", label: "Application Load Balancer" }
    EC2@{ svc: "Amazon EC2", label: "インスタンス（CloudWatch エージェント）" }
  end
  S3@{ svc: "Amazon S3", label: "✔ A: アクセスログの保存先" }
  CWL@{ svc: "Amazon CloudWatch Logs", label: "✔ B: アプリケーションのログ" }
  CLI -- "HTTP リクエスト" --> ALB --> EC2
  ALB == "✔ A: アクセスログ（既定は無効）" ==> S3
  EC2 == "✔ B: ログファイル" ==> CWL
  W["⚠ D: フローログは IP の通信だけ<br/>⚠ E: CloudTrail はログファイルを集めない"]
  W -.- VPC
